using Godot;
using System;
using System.Collections.Generic;
using Settings=Godot.Collections.Dictionary;
using GArray=Godot.Collections.Array;

public partial class AudioEffectsOperations
{
    public Settings automation_commands(string type)=>type switch {"gain"=>new Settings {["db"]="volume"},"hq_pitch"=>new Settings {["semitones"]="pitch"},"time_warp"=>new Settings {["tempo"]="tempo"},"lowpass" or "highpass" or "bandpass" or "notch"=>new Settings {["frequency"]="frequency",["q"]="width"},"eq"=>new Settings {["frequency"]="frequency",["q"]="width",["db"]="gain"},"low_shelf" or "high_shelf"=>new Settings {["frequency"]="frequency",["db"]="gain"},"compressor"=>new Settings {["threshold"]="threshold",["ratio"]="ratio",["makeup"]="makeup"},"gate" or "breath"=>new Settings {["ratio"]="ratio"},"frequency_shift"=>new Settings {["shift"]="shift"},"bitcrusher"=>new Settings {["bits"]="bits",["reduction"]="samples"},"noise_reduce"=>new Settings {["reduction"]="noise_reduction",["floor"]="noise_floor"},_=>new Settings()};
    private static double Sample(IReadOnlyList<Settings> points,double time,double fallback){if(points.Count==0)return fallback;if(time<=Value(points[0],"time"))return Value(points[0],"value");for(int index=1;index<points.Count;index++){var a=points[index-1];var b=points[index];if(time<Value(b,"time")){if(Text(a,"curve","linear")=="hold")return Value(a,"value");double weight=Math.Clamp((time-Value(a,"time"))/Math.Max(.000001,Value(b,"time")-Value(a,"time")),0,1);if(Text(a,"curve","linear")=="smooth")weight=Mathf.SmoothStep(0,1,weight);return Mathf.Lerp(Value(a,"value"),Value(b,"value"),weight);}}return Value(points[^1],"value");}
    private static List<Settings> Points(GArray source){var result=new List<Settings>();foreach(var raw in source)result.Add(raw.AsGodotDictionary());return result;}
    public double automation_value(GArray points,double time,double fallback)=>Sample(Points(points),time,fallback);
    public GArray evaluated_stack(GArray stack,double time){var output=new GArray();foreach(var raw in stack){var effect=raw.AsGodotDictionary().Duplicate(true);var automation=Get(effect,"automation",new Settings()).AsGodotDictionary();var parameters=Parameters(effect);foreach(var pair in automation){var points=pair.Value.AsGodotArray();if(points.Count>0)parameters[pair.Key]=automation_value(points,time,parameters.TryGetValue(pair.Key,out var fallback)?fallback.AsDouble():0);}output.Add(effect);}return output;}
    public string automated_filter(Settings effect,int rate,string filter,string context)
    {
        var automation=Get(effect,"automation",new Settings()).AsGodotDictionary();if(filter.Length==0||automation.Count==0)return filter;string type=Text(effect,"type");if(type=="hq_pitch")filter=filter.Replace("pitchq=quality","pitchq=consistency",StringComparison.Ordinal);var mapping=automation_commands(type);string first=filter.Split('=')[0],target=first+"@kiwi_"+context.Sha256Text()[..12];var commands=new List<string>();var fields=new Dictionary<string,Settings>();var defined=definition(type);if(defined.TryGetValue("parameters",out var parameters))foreach(var raw in parameters.AsGodotArray()){var field=raw.AsGodotDictionary();fields[Text(field,"id")]=field;}foreach(var pair in automation){string key=pair.Key.AsString();if(!mapping.ContainsKey(key))continue;var points=pair.Value.AsGodotArray();if(points.Count==0)continue;double duration=0;foreach(var raw in points)duration=Math.Max(duration,Value(raw.AsGodotDictionary(),"time"));double interval=Math.Max(.02,duration/5000);int count=Math.Max(1,(int)Math.Ceiling(duration/interval));var ordered=Points(points);ordered.Sort((a,b)=>Value(a,"time").CompareTo(Value(b,"time")));string previous="";for(int step=0;step<=count;step++){double time=Math.Min(duration,step*interval),value=Sample(ordered,time,Value(Parameters(effect),key));double minimum=-100000,maximum=100000;if(fields.TryGetValue(key,out var field)){minimum=Value(field,"min");maximum=Value(field,"max");}value=Math.Clamp(value,minimum,maximum);if(key=="frequency")value=Math.Min(value,rate*.45);string argument=number(value);if(key is "threshold" or "makeup"&&type is "compressor" or "gate" or "breath")argument=number(Mathf.DbToLinear(value));if(type=="gain")argument+="dB";if(type=="hq_pitch"&&key=="semitones")argument=number(Math.Pow(2,value/12));if(argument!=previous){commands.Add(number(time)+" "+target+" "+mapping[key].AsString()+" "+argument);previous=argument;}}}return commands.Count==0?filter:"asendcmd=c='"+string.Join(';',commands)+"',"+target+filter[first.Length..];
    }
    public string rendered_filter(Settings effect,int rate,string context){string filter=automated_filter(effect,rate,offline_filter(effect,rate),context);if(filter.Length>0&&Text(effect,"type")=="noise_reduce"){int latency=2*(rate/80);filter="apad=pad_len="+latency+","+filter+",atrim=start_sample="+latency+",asetpts=PTS-STARTPTS";}return filter;}
    public string chain(GArray effects,int rate,string context){var filters=new List<string>();for(int index=0;index<effects.Count;index++){string filter=rendered_filter(effects[index].AsGodotDictionary(),rate,context+index);if(filter.Length>0)filters.Add(filter);}return string.Join(',',filters);}
    public double tail_seconds(GArray effects)
    {
        double tail=0;foreach(var raw in effects){var effect=raw.AsGodotDictionary();if(!Enabled(effect))continue;var p=Parameters(effect);string type=Text(effect,"type");if(type=="doppler")tail+=GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioDoppler.cs").Call("tail_seconds",p).AsDouble();if(type is "convolution" or "plate" or "spring" or "pingpong"&&Value(p,"mix",.3)>0)tail+=GD.Load<CSharpScript>("res://Workspaces/AudioWorkspace/KiwiAudioImpulse.cs").Call("duration",type,p).AsDouble();if(type=="early_reflections"&&Value(p,"mix",.25)>0)tail+=.067*(.5+Value(p,"size",.5));if(type=="stereo_delay")tail+=Math.Max(Value(p,"left",20),Value(p,"right",65))/1000;if(type=="delay"&&Value(p,"mix",.3)>0)tail+=Value(p,"time",.25)*(Value(p,"feedback",.35)<=0?1:8);if(type=="reverb"&&Value(p,"mix",.25)>0)tail+=4*Value(p,"size",.6)+.5;}return Math.Min(tail,30);
    }
}
